entries.quadlet:
[Container]
Image={{ .Image }}
ContainerName={{ .Name }}
Volume={{ .Volumes.work }}:/opt/adguardhome/work:Z
Volume={{ .Volumes.conf }}:/opt/adguardhome/conf:Z
Network={{ .Network }}
PublishPort=53:53/tcp
PublishPort=53:53/udp

[Container]
Image={{ .Image }}
ContainerName={{ .Name }}
Network={{ .Network }}
Environment=USER_GID=1000
Environment=USER_UID=1000
Environment=TZ={{ .Settings.TZ }}
Volume={{ .Volumes.data }}:/data:Z
PublishPort=2222:22

components.quadlet:
[Container]
Image={{ .Image }}
Environment=TZ={{ .Settings.TZ }}
Environment=DB_PASSWORD={{ .Settings.DB_PASSWORD }}
Environment=DB_USERNAME=postgres
Environment=DB_DATABASE_NAME=immich
Volume={{ .Volumes.library }}:/data:Z

[Container]
Image={{ .Image }}
HealthCmd=redis-cli ping | grep -q PONG || exit 1

entries.quadlet:
[Container]
Image={{ .Image }}
ContainerName={{ .Name }}
Environment=TZ={{ .Settings.TZ }}
Volume={{ .Volumes.config }}:/config:Z
Volume={{ .Volumes.cache }}:/cache:Z
Volume={{ .Volumes.media }}:/media:Z
Network={{ .Network }}

[Container]
Image={{ .Image }}
ContainerName={{ .Name }}
Environment=EULA={{ .Settings.EULA }}
Environment=VERSION={{ .Settings.VERSION }}
Environment=MEMORY={{ .Settings.MEMORY }}
Environment=MOTD={{ .Settings.MOTD }}
Environment=TZ={{ .Settings.TZ }}
Volume={{ .Volumes.data }}:/data:Z
Network={{ .Network }}
PublishPort=25565:25565/tcp

[Container]
Image={{ .Image }}
ContainerName={{ .Name }}
Network={{ .Network }}
Environment=FTLCONF_dns_listeningMode=all
Environment="FTLCONF_webserver_api_password={{ .Settings.WEB_PASSWORD }}"
Environment="TZ={{ .Settings.TZ }}"
Volume={{ .Volumes.pihole }}:/etc/pihole:Z
PublishPort=53:53
PublishPort=53:53/udp
